WITH unpacked AS (SELECT id, status_code, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, SHIFTRIGHT(status_code, 2) AS status_code_high, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, context['version'] AS version FROM app_logs) SELECT id, status_code, version, MAX(status_code) OVER w_recent AS last7_max_status_code, COUNT(status_code) OVER w_recent AS last7_count_status_code, SUM(status_code) OVER w_recent AS last7_sum_status_code FROM unpacked WHERE duration_sec > 1.7 WINDOW w_recent AS (ORDER BY status_code ASC, id ASC ROWS BETWEEN 6 PRECEDING AND CURRENT ROW);
